"use strict";

var bind = require("./binder");
var call = require("./plain-call");
var applyList = require("./pick-apply");

module.exports = function unbound(parts) {
  if (parts.length < 1 || typeof parts[0] !== "function") {
    throw new TypeError("a function is required");
  }
  return applyList(bind, call, parts);
};
